fn solve(n: i8) -> i8 {
    // If n is odd, no rectangle with integer sides can have this perimeter
    if n % 2 != 0 {
        return 0;
    }
    
    // n is even, so we can work with half-perimeter
    let half = n / 2;
    
    // Count unordered pairs (a, b) with a < b and a + b = half
    // This is equivalent to counting integers a such that:
    // 1 <= a < half - a
    // => a < half - a
    // => 2a < half
    // => a < half / 2
    
    // The number of positive integers a satisfying a < half / 2
    // is floor((half - 1) / 2) when half is integer
    
    let mut count = (half - 1) / 2;
    
    // Adjust for squares (a = b case)
    // When half is even, a = half/2 gives a = b, which is a square
    if half % 2 == 0 {
        count -= 1;
    }
    
    // Ensure non-negative result
    if count < 0 {
        0
    } else {
        count
    }
}